#if UNITY_EDITOR
using System.IO;
using UnityEditor;
using UnityEditor.Build;
using UnityEditor.Build.Reporting;
using UnityEditor.SceneManagement;
using UnityEngine;

public static class Quest3BuildTools
{
    [MenuItem("Tools/Quest3 VR/Quick Switch To Android")]
    public static void SwitchToAndroid()
    {
        // Why: reduce foot-guns. You’ll build straight to Quest.
        EditorUserBuildSettings.SwitchActiveBuildTarget(BuildTargetGroup.Android, BuildTarget.Android);
        PlayerSettings.colorSpace = ColorSpace.Linear;
        PlayerSettings.SetArchitecture(BuildTargetGroup.Android, 1); // ARM64
        PlayerSettings.Android.minSdkVersion = AndroidSdkVersions.AndroidApiLevel29;
        PlayerSettings.defaultInterfaceOrientation = UIOrientation.LandscapeLeft;
        Debug.Log("[Quest3] Android target set. Remember to enable OpenXR in Project Settings > XR Plug-in Management.");
    }

    [MenuItem("Tools/Quest3 VR/Create Sample Scene")]
    public static void CreateSampleScene()
    {
        var dir = "Assets/Scenes";
        if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);
        var newScene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
        var bootstrap = new GameObject("Quest3Bootstrap");
        bootstrap.AddComponent<Bootstrap>();
        EditorSceneManager.SaveScene(newScene, $"{dir}/Main.unity");
        Debug.Log("[Quest3] Sample scene created at Assets/Scenes/Main.unity");
    }

    [MenuItem("Tools/Quest3 VR/Build & Run (Quest3)")]
    public static void BuildAndRun()
    {
        SwitchToAndroid();
        var scenes = new[] {"Assets/Scenes/Main.unity"};
        if (!File.Exists(scenes[0])) CreateSampleScene();

        var buildPlayerOptions = new BuildPlayerOptions
        {
            scenes = scenes,
            locationPathName = "Builds/Quest3/Quest3RoguelikeVR.apk",
            target = BuildTarget.Android,
            options = BuildOptions.AutoRunPlayer | BuildOptions.Development
        };
        var report = BuildPipeline.BuildPlayer(buildPlayerOptions);
        Debug.Log($"[Quest3] Build result: {report.summary.result}, Size: {report.summary.totalSize/1_000_000f:0.0} MB");
    }
}
#endif

