using UnityEngine;
using UnityEngine.SpatialTracking;

public class Bootstrap : MonoBehaviour
{
    [Header("Generation")]
    public int roomCount = 6;
    public int roomSize = 8; // meters
    public int corridorWidth = 3;
    public int seed = 0;

    [Header("Gameplay")]
    public int initialEnemies = 6;

    private void Awake()
    {
        if (FindObjectOfType<PlayerRig>() == null) PlayerRig.CreateRig();
        if (FindObjectOfType<DungeonGenerator>() == null)
        {
            var go = new GameObject("Dungeon");
            var gen = go.AddComponent<DungeonGenerator>();
            gen.roomCount = roomCount;
            gen.roomSize = roomSize;
            gen.corridorWidth = corridorWidth;
            gen.seed = seed == 0 ? Random.Range(1, int.MaxValue) : seed;
            gen.Generate();
        }
        if (FindObjectOfType<Spawner>() == null)
        {
            var go = new GameObject("Spawners");
            var sp = go.AddComponent<Spawner>();
            sp.initialEnemies = initialEnemies;
        }
        if (FindObjectOfType<Director>() == null)
        {
            var go = new GameObject("Director");
            go.AddComponent<Director>();
        }
        if (FindObjectOfType<LootUI>() == null)
        {
            var ui = new GameObject("LootUI");
            ui.AddComponent<LootUI>();
        }
    }
}

