using UnityEngine;
using UnityEngine.XR;
using System.Collections.Generic;

[RequireComponent(typeof(CharacterController))]
public class PlayerRig : MonoBehaviour
{
    public static PlayerRig Instance { get; private set; }

    public Camera hmdCamera;
    CharacterController cc;

    public static void CreateRig()
    {
        var rigRoot = new GameObject("PlayerRig");
        var cc = rigRoot.AddComponent<CharacterController>();
        cc.height = 1.7f; cc.radius = 0.3f; cc.center = new Vector3(0, 0.85f, 0);

        var camGo = new GameObject("MainCamera");
        camGo.tag = "MainCamera";
        var cam = camGo.AddComponent<Camera>();
        cam.nearClipPlane = 0.02f;
        camGo.AddComponent<TrackedPoseDriver>(); // HMD tracking

        camGo.transform.SetParent(rigRoot.transform, false);
        camGo.transform.localPosition = new Vector3(0, 1.6f, 0);

        var rig = rigRoot.AddComponent<PlayerRig>();
        rig.hmdCamera = cam;
        rigRoot.AddComponent<SimpleVRLocomotion>();
        rigRoot.AddComponent<PlayerCombat>();
        Debug.Log("[Quest3] PlayerRig created.");
    }

    private void Awake()
    {
        if (Instance != null && Instance != this) { Destroy(gameObject); return; }
        Instance = this;
        cc = GetComponent<CharacterController>();
    }

    private void Update()
    {
        // Why: keep collider under HMD horizontally for natural head movement.
        var headOffset = hmdCamera.transform.localPosition;
        var pos = transform.position;
        pos.x += headOffset.x;
        pos.z += headOffset.z;
        transform.position = pos;
    }
}

