using UnityEngine;
using UnityEngine.XR;
using System.Collections;

[RequireComponent(typeof(CharacterController))]
public class SimpleVRLocomotion : MonoBehaviour
{
    CharacterController cc;
    Transform cam;

    [Header("Movement")]
    public float walkSpeed = 1.6f;
    public float runSpeed = 3.0f;
    public bool vignetteOnMove = true;

    [Header("Snap Turn")]
    public float snapAngle = 30f;
    public float snapDeadzone = 0.5f;
    private bool canSnap = true;

    [Header("Dash")]
    public float dashDistance = 3f;
    public float dashCooldown = 1.0f;
    bool canDash = true;

    VignetteCurtain curtain;

    InputDevice leftHand, rightHand;

    void Start()
    {
        cc = GetComponent<CharacterController>();
        cam = Camera.main.transform;
        curtain = VignetteCurtain.Create();
        TryBindDevices();
        StartCoroutine(RebindDevicesRoutine());
    }

    IEnumerator RebindDevicesRoutine()
    {
        while (true) { if (!leftHand.isValid || !rightHand.isValid) TryBindDevices(); yield return new WaitForSeconds(1f); }
    }

    void TryBindDevices()
    {
        var lefts = new System.Collections.Generic.List<InputDevice>();
        var rights = new System.Collections.Generic.List<InputDevice>();
        InputDevices.GetDevicesAtXRNode(XRNode.LeftHand, lefts);
        InputDevices.GetDevicesAtXRNode(XRNode.RightHand, rights);
        if (lefts.Count > 0) leftHand = lefts[0];
        if (rights.Count > 0) rightHand = rights[0];
    }

    void Update()
    {
        Vector2 moveAxis = Vector2.zero;
        if (!leftHand.isValid) TryBindDevices();
        leftHand.TryGetFeatureValue(CommonUsages.primary2DAxis, out moveAxis);

        var isRun = false;
        leftHand.TryGetFeatureValue(CommonUsages.primaryButton, out isRun); // X/A held -> run

        var speed = isRun ? runSpeed : walkSpeed;
        var forward = cam.forward; forward.y = 0; forward.Normalize();
        var right = cam.right; right.y = 0; right.Normalize();
        var move = (forward * moveAxis.y + right * moveAxis.x) * speed;

        if (vignetteOnMove) curtain.SetIntensity(Mathf.Clamp01(moveAxis.magnitude * 0.6f));
        cc.SimpleMove(move);

        // Snap turn on right stick x
        Vector2 turnAxis = Vector2.zero;
        rightHand.TryGetFeatureValue(CommonUsages.primary2DAxis, out turnAxis);
        if (canSnap && Mathf.Abs(turnAxis.x) > snapDeadzone)
        {
            transform.Rotate(0, Mathf.Sign(turnAxis.x) * snapAngle, 0);
            canSnap = false;
            Invoke(nameof(ResetSnap), 0.25f);
        }

        // Dash on A or X
        bool dashPressed = false;
        rightHand.TryGetFeatureValue(CommonUsages.primaryButton, out dashPressed);
        if (dashPressed && canDash) StartCoroutine(Dash());
    }

    IEnumerator Dash()
    {
        canDash = false;
        curtain.SetIntensity(0.9f);
        var dir = new Vector3(Camera.main.transform.forward.x, 0, Camera.main.transform.forward.z).normalized;
        var target = transform.position + dir * dashDistance;
        float t = 0;
        while (t < 1f)
        {
            t += Time.deltaTime * 8f;
            transform.position = Vector3.Lerp(transform.position, target, t);
            yield return null;
        }
        curtain.SetIntensity(0);
        yield return new WaitForSeconds(dashCooldown);
        canDash = true;
    }

    void ResetSnap() => canSnap = true;
}

