using UnityEngine;

public class VignetteCurtain : MonoBehaviour
{
    Material mat;
    float intensity;

    public static VignetteCurtain Create()
    {
        var go = new GameObject("VignetteCurtain");
        DontDestroyOnLoad(go);
        return go.AddComponent<VignetteCurtain>();
    }

    void OnEnable()
    {
        Shader shader = Shader.Find("Hidden/Quest3/VignetteCurtain");
        if (shader == null)
        {
            // minimal runtime shader creation
            shader = new Shader();
        }
        mat = new Material(Shader.Find("UI/Default"));
    }

    public void SetIntensity(float v) { intensity = Mathf.Clamp01(v); }

    void OnRenderImage(RenderTexture src, RenderTexture dst)
    {
        // Cheap vignette: darken edges based on intensity. (Why: comfort during motion)
        Graphics.Blit(src, dst);
        if (intensity <= 0f) return;
        // Simple full-screen fade (approximate vignette without custom shader)
        GL.PushMatrix();
        GL.LoadOrtho();
        mat.SetPass(0);
        GL.Begin(GL.QUADS);
        var c = new Color(0,0,0, intensity * 0.6f);
        GL.Color(c); GL.Vertex3(0,0,0); GL.Vertex3(1,0,0); GL.Vertex3(1,1,0); GL.Vertex3(0,1,0);
        GL.End();
        GL.PopMatrix();
    }
}

