using UnityEngine;
using System.Collections.Generic;

public class DungeonGenerator : MonoBehaviour
{
    public int roomCount = 6;
    public int roomSize = 8;
    public int corridorWidth = 3;
    public int seed = 12345;

    public GameObject blockPrefab;

    const float BLOCK = 1f;

    System.Random rng;
    HashSet<Vector3Int> occupied = new HashSet<Vector3Int>();

    public void Generate()
    {
        rng = new System.Random(seed);
        if (blockPrefab == null)
        {
            blockPrefab = DestructibleBlock.CreatePrefab();
        }
        var cursor = Vector3Int.zero;
        for (int i = 0; i < roomCount; i++)
        {
            var size = new Vector3Int(roomSize, 4, roomSize);
            BuildRoom(cursor, size);

            if (i < roomCount - 1)
            {
                var dir = RandomDir2D();
                var length = rng.Next(roomSize/2, roomSize);
                BuildCorridor(cursor, dir, length, corridorWidth);
                cursor += dir * length;
            }
        }
        // Add floor colliders
        var floor = new GameObject("NavFloor");
        var box = floor.AddComponent<BoxCollider>();
        box.center = new Vector3(0, 0, 0);
        box.size = new Vector3(roomCount * roomSize * 1.2f, 0.1f, roomCount * roomSize * 1.2f);
        floor.transform.position = Vector3.zero;
    }

    Vector3Int RandomDir2D()
    {
        var opts = new[] { Vector3Int.right, Vector3Int.left, Vector3Int.forward, Vector3Int.back };
        return opts[rng.Next(opts.Length)];
    }

    void BuildRoom(Vector3Int center, Vector3Int size)
    {
        // Walls shell; interior empty. (Why: keep block count moderate for Quest)
        var half = size / 2;
        for (int x = -half.x; x <= half.x; x++)
        for (int y = 0; y < size.y; y++)
        for (int z = -half.z; z <= half.z; z++)
        {
            bool isWall = (x == -half.x || x == half.x || z == -half.z || z == half.z) && y < size.y;
            bool isFloor = y == 0;
            if (isWall || isFloor)
            {
                PlaceBlock(center + new Vector3Int(x, y, z));
            }
        }
    }

    void BuildCorridor(Vector3Int start, Vector3Int dir, int length, int width)
    {
        var half = width / 2;
        for (int i = 0; i < length; i++)
        {
            var basePos = start + dir * i;
            for (int w = -half; w <= half; w++)
            {
                var offset = (dir.x != 0) ? new Vector3Int(0,0,w) : new Vector3Int(w,0,0);
                PlaceBlock(basePos + new Vector3Int(0,0,0) + offset); // floor
                for (int h=1; h<4; h++)
                {
                    PlaceBlock(basePos + offset + new Vector3Int(dir.z!=0?half+1: (w== -half? -half: half), h, dir.x!=0?half+1: (w== -half? -half: half)));
                }
            }
        }
    }

    void PlaceBlock(Vector3Int grid)
    {
        if (occupied.Contains(grid)) return;
        occupied.Add(grid);
        var b = Instantiate(blockPrefab, (Vector3)grid * BLOCK, Quaternion.identity, transform);
    }
}

