using UnityEngine;
using System.Collections.Generic;

public class DestructibleBlock : MonoBehaviour, IDamageable
{
    public float hp = 20f;

    static GameObject prefab;

    // Why: create a shared simple cube prefab with collider + script, if not provided.
    public static GameObject CreatePrefab()
    {
        if (prefab != null) return prefab;
        prefab = GameObject.CreatePrimitive(PrimitiveType.Cube);
        prefab.name = "DestructibleBlock";
        prefab.transform.localScale = Vector3.one;
        var db = prefab.AddComponent<DestructibleBlock>();
        var rb = prefab.AddComponent<Rigidbody>(); rb.isKinematic = true; // static until destroyed
        var mr = prefab.GetComponent<MeshRenderer>(); mr.sharedMaterial = new Material(Shader.Find("Standard"));
        return prefab;
    }

    public void ApplyDamage(float amount, Vector3 hitPoint, Vector3 hitNormal)
    {
        hp -= amount;
        if (hp <= 0) DestroyBlock(hitPoint, hitNormal);
    }

    void DestroyBlock(Vector3 hit, Vector3 normal)
    {
        SpawnDebris();
        Destroy(gameObject);
    }

    static Queue<Rigidbody> debrisPool = new Queue<Rigidbody>();

    void SpawnDebris()
    {
        for (int i = 0; i < 4; i++)
        {
            Rigidbody rb;
            if (debrisPool.Count > 0) rb = debrisPool.Dequeue();
            else
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.transform.localScale = Vector3.one * 0.3f;
                rb = go.AddComponent<Rigidbody>();
                rb.mass = 0.2f;
                go.GetComponent<MeshRenderer>().sharedMaterial = new Material(Shader.Find("Standard"));
                go.AddComponent<DebrisAutoDespawn>();
            }
            rb.transform.position = transform.position + Random.insideUnitSphere * 0.2f;
            rb.gameObject.SetActive(true);
            rb.velocity = Random.insideUnitSphere * 2f + Vector3.up * 1f;
        }
    }

    public static void ReturnDebris(Rigidbody rb)
    {
        rb.gameObject.SetActive(false); debrisPool.Enqueue(rb);
    }
}

public class DebrisAutoDespawn : MonoBehaviour
{
    float t;
    void OnEnable() { t = 0; }
    void Update()
    {
        t += Time.deltaTime;
        if (t > 2.5f)
        {
            var rb = GetComponent<Rigidbody>();
            DestructibleBlock.ReturnDebris(rb);
        }
    }
}

public interface IDamageable
{
    void ApplyDamage(float amount, Vector3 hitPoint, Vector3 hitNormal);
}

