using UnityEngine;
using UnityEngine.XR;

public class PlayerCombat : MonoBehaviour
{
    public float fireCooldown = 0.15f;
    public float rayDamage = 15f;
    public float maxRange = 12f;
    float lastFire;
    LineRenderer lr;

    InputDevice right;

    void Start()
    {
        lr = gameObject.AddComponent<LineRenderer>();
        lr.startWidth = lr.endWidth = 0.01f;
        lr.positionCount = 2;
        lr.enabled = false;
        TryBindRight();
    }

    void TryBindRight()
    {
        var rights = new System.Collections.Generic.List<InputDevice>();
        InputDevices.GetDevicesAtXRNode(XRNode.RightHand, rights);
        if (rights.Count > 0) right = rights[0];
    }

    void Update()
    {
        if (!right.isValid) TryBindRight();

        bool trigger;
        right.TryGetFeatureValue(CommonUsages.triggerButton, out trigger);
        if (trigger && Time.time - lastFire > fireCooldown)
        {
            lastFire = Time.time;
            Shoot();
        }
    }

    void Shoot()
    {
        var cam = Camera.main;
        var ray = new Ray(cam.transform.position, cam.transform.forward);
        lr.enabled = true;
        lr.SetPosition(0, ray.origin);
        if (Physics.Raycast(ray, out var hit, maxRange))
        {
            lr.SetPosition(1, hit.point);
            var dmg = hit.collider.GetComponentInParent<IDamageable>();
            if (dmg != null) dmg.ApplyDamage(rayDamage, hit.point, hit.normal);
        }
        else
        {
            lr.SetPosition(1, ray.origin + ray.direction * maxRange);
        }
        Invoke(nameof(HideLR), 0.03f);
    }

    void HideLR() => lr.enabled = false;
}

