using UnityEngine;

[RequireComponent(typeof(CharacterController))]
public class Enemy : MonoBehaviour, IDamageable
{
    public float hp = 30f;
    public float speed = 1.2f;
    CharacterController cc;

    void Start() { cc = GetComponent<CharacterController>(); }

    void Update()
    {
        if (PlayerRig.Instance == null) return;
        var dir = (PlayerRig.Instance.transform.position - transform.position);
        dir.y = 0;
        if (dir.magnitude > 0.1f) cc.SimpleMove(dir.normalized * speed);
    }

    public void ApplyDamage(float amount, Vector3 hitPoint, Vector3 hitNormal)
    {
        hp -= amount;
        if (hp <= 0) Die();
    }

    void Die()
    {
        LootDrop.Spawn(transform.position + Vector3.up * 0.5f);
        Destroy(gameObject);
    }
}

