using UnityEngine;

public class Spawner : MonoBehaviour
{
    public int initialEnemies = 6;

    void Start()
    {
        for (int i = 0; i < initialEnemies; i++)
        {
            var e = CreateEnemy();
            e.transform.position = Random.insideUnitSphere * 6f + Vector3.up * 0.5f;
        }
    }

    GameObject CreateEnemy()
    {
        var go = GameObject.CreatePrimitive(PrimitiveType.Capsule);
        go.name = "Enemy";
        Destroy(go.GetComponent<CapsuleCollider>());
        var cc = go.AddComponent<CharacterController>();
        cc.height = 1.6f; cc.radius = 0.3f;
        go.AddComponent<Enemy>();
        go.GetComponent<MeshRenderer>().sharedMaterial = new Material(Shader.Find("Standard"));
        return go;
    }
}

