using UnityEngine;

public class Director : MonoBehaviour
{
    // Tiny pacing: spawn heal orb if quiet too long; otherwise add an enemy.
    public float checkInterval = 7f;
    float sinceCombat;
    int lastKillCount;

    void Start() { InvokeRepeating(nameof(Tick), checkInterval, checkInterval); }

    void Update()
    {
        sinceCombat += Time.deltaTime;
        if (LootDrop.kills != lastKillCount)
        {
            sinceCombat = 0;
            lastKillCount = LootDrop.kills;
        }
    }

    void Tick()
    {
        if (sinceCombat > 12f)
        {
            HealOrb.Spawn(PlayerRig.Instance.transform.position + Random.onUnitSphere * 2f);
            sinceCombat = 0;
        }
        else
        {
            var sp = FindObjectOfType<Spawner>();
            if (sp != null)
            {
                var e = sp.gameObject.AddComponent<SpawnerHelper>().CreateOnce();
                e.transform.position = PlayerRig.Instance.transform.position + Random.onUnitSphere * 5f;
            }
        }
    }
}

public class SpawnerHelper : MonoBehaviour
{
    public GameObject CreateOnce()
    {
        var go = GameObject.CreatePrimitive(PrimitiveType.Capsule);
        go.name = "Enemy";
        Destroy(go.GetComponent<CapsuleCollider>());
        var cc = go.AddComponent<CharacterController>();
        cc.height = 1.6f; cc.radius = 0.3f;
        go.AddComponent<Enemy>();
        go.GetComponent<MeshRenderer>().sharedMaterial = new Material(Shader.Find("Standard"));
        return go;
    }
}

public class HealOrb : MonoBehaviour
{
    public static void Spawn(Vector3 pos)
    {
        var go = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        go.transform.position = pos;
        go.transform.localScale = Vector3.one * 0.25f;
        var rb = go.AddComponent<Rigidbody>();
        rb.useGravity = false;
        go.AddComponent<HealOrb>();
    }

    void OnTriggerEnter(Collider other)
    {
        if (other.GetComponent<PlayerRig>())
        {
            // Proxy “heal”: slow down enemies for a moment (mercy).
            foreach (var e in FindObjectsOfType<Enemy>()) e.speed = 0.6f;
            Destroy(gameObject);
        }
    }
}

