using UnityEngine;
using System.Collections.Generic;

public enum ItemRarity { Common, Magic, Rare, Legendary }

[System.Serializable]
public class Affix
{
    public string id; public string stat; public float min; public float max;
    public Affix(string id, string stat, float min, float max){ this.id=id; this.stat=stat; this.min=min; this.max=max;}
}

public class Item
{
    public string type;
    public int level;
    public ItemRarity rarity;
    public List<(Affix,float)> affixes = new();

    public override string ToString()
    {
        var s = $"{rarity} {type} (ilvl {level})";
        foreach (var (a,val) in affixes) s += $"\n • {a.id} {a.stat} +{val:0}";
        return s;
    }
}

public static class ItemGenerator
{
    static System.Random rng = new System.Random();
    static readonly string[] Types = {"Sword","Axe","Staff","Chest","Ring"};

    static readonly List<Affix> Pool = new()
    {
        new Affix("Feral","Dexterity",10,30),
        new Affix("Hardened","Armor",10,40),
        new Affix("of Flames","Fire Dmg",3,10),
        new Affix("Champion's","Strength",15,50),
        new Affix("Eagle","CritChance%",2,8),
    };

    public static Item Generate(int level)
    {
        var item = new Item();
        item.level = level;
        item.type = Types[rng.Next(Types.Length)];
        item.rarity = RollRarity();

        int affixCount = item.rarity switch { ItemRarity.Common => 0, ItemRarity.Magic => 1, ItemRarity.Rare => 3, _ => 4 };
        for (int i = 0; i < affixCount; i++)
        {
            var a = Pool[rng.Next(Pool.Count)];
            var roll = Mathf.Lerp((float)a.min, (float)a.max, (float)rng.NextDouble());
            item.affixes.Add((a, roll));
        }
        if (item.rarity == ItemRarity.Legendary)
        {
            // Simple unique hook (why: sense of chase)
            item.affixes.Add((new Affix("Phoenix", "OnHit Fireball", 1, 1), 1));
        }
        return item;
    }

    static ItemRarity RollRarity()
    {
        int r = rng.Next(100);
        if (r < 75) return ItemRarity.Common;
        if (r < 95) return ItemRarity.Magic;
        if (r < 99) return ItemRarity.Rare;
        return ItemRarity.Legendary;
    }
}

