#if UNITY_EDITOR
using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEditor.PackageManager;
using UnityEditor.PackageManager.Requests;
using UnityEditor.Rendering;
using UnityEditor.XR.Management;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using UnityEngine.XR;
using UnityEngine.XR.Management;

// WHY: One-click project bootstrap for Quest 3 (URP + OpenXR) with conservative mobile caps.
public static class Quest3URPAndOpenXRSetup
{
    private const string SettingsDir = "Assets/Settings";
    private const string URPDir = SettingsDir + "/URP";
    private const string XRDir = SettingsDir + "/XR";

    private static readonly string[] RequiredPackages =
    {
        "com.unity.render-pipelines.universal",
        "com.unity.xr.management",
        "com.unity.xr.openxr"
        // Optional: "com.meta.xr.sdk.core", "com.unity.xr.meta-openxr" (if you want Meta extras)
    };

    [MenuItem("Tools/Quest3 VR/Setup: URP + Mobile Caps + OpenXR (Quest)")]
    public static void DoEverything()
    {
        try
        {
            EnsureFolders();
            InstallPackagesBlocking(RequiredPackages);

            SetupPlayerSettingsForQuest();
            var (urp, renderer) = CreateOrLoadURPAssets();
            ApplyMobileURPCaps(urp, renderer);
            AssignURPGlobally(urp);

            EnableOpenXRFor(BuildTargetGroup.Android);
            EnableOpenXRFor(BuildTargetGroup.Standalone);

            EditorUtility.DisplayDialog("Quest 3 Setup", "Done. URP + OpenXR configured.\nBuild: Tools ▸ Quest3 VR ▸ Build & Run", "OK");
        }
        catch (Exception ex)
        {
            Debug.LogError("[Quest3] Setup failed: " + ex);
            EditorUtility.DisplayDialog("Quest 3 Setup", "FAILED. See Console.", "OK");
        }
    }

    // ---------- Folders ----------
    private static void EnsureFolders()
    {
        if (!AssetDatabase.IsValidFolder("Assets/Settings")) AssetDatabase.CreateFolder("Assets", "Settings");
        if (!AssetDatabase.IsValidFolder(URPDir)) AssetDatabase.CreateFolder(SettingsDir.Replace("Assets/","Assets"), "URP");
        if (!AssetDatabase.IsValidFolder(XRDir)) AssetDatabase.CreateFolder(SettingsDir.Replace("Assets/","Assets"), "XR");
    }

    // ---------- Packages ----------
    private static void InstallPackagesBlocking(IEnumerable<string> ids)
    {
        // WHY: Make the action idempotent; ignore already-installed packages.
        var list = Client.List(true, true);
        while (!list.IsCompleted) { }
        var installed = new HashSet<string>(list.Result.Select(p => p.name));

        foreach (var id in ids)
        {
            if (installed.Contains(id)) continue;
            var add = Client.Add(id);
            while (!add.IsCompleted) { }
            if (add.Status == StatusCode.Failure) throw new Exception("Package install failed: " + id + " :: " + add.Error);
        }
        AssetDatabase.Refresh();
    }

    // ---------- Player/Build Settings ----------
    private static void SetupPlayerSettingsForQuest()
    {
        EditorUserBuildSettings.SwitchActiveBuildTarget(BuildTargetGroup.Android, BuildTarget.Android);
        PlayerSettings.colorSpace = ColorSpace.Linear; // WHY: better lighting stability
        PlayerSettings.SetUseDefaultGraphicsAPIs(BuildTarget.Android, false);
        PlayerSettings.SetGraphicsAPIs(BuildTarget.Android, new[] { GraphicsDeviceType.Vulkan, GraphicsDeviceType.OpenGLES3 });
        PlayerSettings.Android.minSdkVersion = AndroidSdkVersions.AndroidApiLevel29;
        PlayerSettings.Android.targetArchitectures = AndroidArchitecture.ARM64;
        PlayerSettings.graphicsJobs = true; // WHY: mobile perf
        PlayerSettings.StripEngineCode = true;
        PlayerSettings.SetManagedStrippingLevel(BuildTargetGroup.Android, ManagedStrippingLevel.High);
        QualitySettings.vSyncCount = 0; // WHY: XR controls sync; avoid double sync
    }

    // ---------- URP Asset Creation ----------
    private static (UniversalRenderPipelineAsset urp, UniversalRendererData renderer)
        CreateOrLoadURPAssets()
    {
        var urpPath = $"{URPDir}/URP_Quest3.asset";
        var rendererPath = $"{URPDir}/URP_Quest3_Renderer.asset";

        var urp = AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(urpPath);
        var renderer = AssetDatabase.LoadAssetAtPath<UniversalRendererData>(rendererPath);

        if (urp == null)
        {
            urp = ScriptableObject.CreateInstance<UniversalRenderPipelineAsset>();
            AssetDatabase.CreateAsset(urp, urpPath);
        }
        if (renderer == null)
        {
            renderer = ScriptableObject.CreateInstance<UniversalRendererData>();
            AssetDatabase.CreateAsset(renderer, rendererPath);
        }

        // Wire renderer into URP via serialized properties (internal fields).
        var so = new SerializedObject(urp);
        var listProp = so.FindProperty("m_RendererDataList");
        if (listProp != null)
        {
            listProp.arraySize = 1;
            listProp.GetArrayElementAtIndex(0).objectReferenceValue = renderer;
        }
        var defIdx = so.FindProperty("m_DefaultRendererIndex");
        if (defIdx != null) defIdx.intValue = 0;
        so.ApplyModifiedPropertiesWithoutUndo();

        EditorUtility.SetDirty(urp);
        EditorUtility.SetDirty(renderer);
        AssetDatabase.SaveAssets();
        return (urp, renderer);
    }

    // ---------- URP Mobile Caps ----------
    private static void ApplyMobileURPCaps(UniversalRenderPipelineAsset urp, UniversalRendererData renderer)
    {
        // Public props (URP 12/14): fall back to SerializedObject if null in older versions.
        TrySetProp(urp, "supportsHDR", false);
        TrySetProp(urp, "msaaSampleCount", 4);
        TrySetProp(urp, "renderScale", 1.0f);
        TrySetProp(urp, "supportsCameraDepthTexture", false);
        TrySetProp(urp, "supportsCameraOpaqueTexture", false);
        TrySetProp(urp, "shadowDistance", 18f);
        TrySetProp(urp, "softShadowsSupported", false);
        TrySetEnumProp(urp, "shadowCascadeCount", 1);
        TrySetEnumProp(urp, "additionalLightsRenderingMode", 1); // PerObject
        TrySetProp(urp, "maxAdditionalLightsCount", 2);

        // Renderer toggles
        var s = new SerializedObject(renderer);
        // Disable post by default (shaders/overhead)
        SetBoolIfExists(s, "m_PostProcessData", false); // if a data ref is required, leave null
        // Decals/SSAO disabled
        SetBoolIfExists(s, "m_AccurateGbufferNormals", false);
        s.ApplyModifiedPropertiesWithoutUndo();

        // Assign URP globally & per-quality
        GraphicsSettings.renderPipelineAsset = urp;
        for (int i = 0; i < QualitySettings.names.Length; i++)
        {
            QualitySettings.SetQualityLevel(i, false);
            QualitySettings.renderPipeline = urp;
            QualitySettings.shadowResolution = ShadowResolution.Medium;
            QualitySettings.anisotropicFiltering = AnisotropicFiltering.Disable;
        }
    }

    // ---------- Assign URP ----------
    private static void AssignURPGlobally(UniversalRenderPipelineAsset urp)
    {
        GraphicsSettings.renderPipelineAsset = urp;
        QualitySettings.renderPipeline = urp;
        EditorUtility.SetDirty(urp);
        AssetDatabase.SaveAssets();
    }

    // ---------- OpenXR Enablement ----------
    private static void EnableOpenXRFor(BuildTargetGroup group)
    {
        // Ensure XRGeneralSettings + XRManagerSettings exist for the target group
        var general = XRGeneralSettingsPerBuildTarget.XRGeneralSettingsForBuildTarget(group);
        if (general == null)
        {
            general = ScriptableObject.CreateInstance<XRGeneralSettings>();
            AssetDatabase.CreateAsset(general, $"{XRDir}/XRGeneralSettings_{group}.asset");
            XRGeneralSettingsPerBuildTarget.SetSettingsForBuildTarget(group, general);
        }

        var manager = general.AssignedSettings;
        if (manager == null)
        {
            manager = ScriptableObject.CreateInstance<XRManagerSettings>();
            manager.name = $"XRManagerSettings_{group}";
            AssetDatabase.AddObjectToAsset(manager, general);
            general.AssignedSettings = manager;
            EditorUtility.SetDirty(general);
        }

        // Add OpenXR loader (idempotent)
        var openxrLoaderType = "UnityEngine.XR.OpenXR.OpenXRLoader";
        XRPackageMetadataStore.AssignLoader(manager, openxrLoaderType, group);

        // Make sure it's first (prefer OpenXR)
        var active = manager.activeLoaders;
        var openxr = active.FirstOrDefault(l => l && l.GetType().FullName == openxrLoaderType);
        if (openxr != null)
        {
            active.Remove(openxr);
            active.Insert(0, openxr);
            manager.TrySetLoaders(active);
            EditorUtility.SetDirty(manager);
        }

        // Enable useful OpenXR features if present
        EnableInteractionProfiles(group);
        AssetDatabase.SaveAssets();
    }

    // Try enabling Oculus Touch, Eye Gaze, Hand tracking, Meta Quest feature if available.
    private static void EnableInteractionProfiles(BuildTargetGroup group)
    {
#if UNITY_OPENXR_1_8_0_OR_NEWER || true
        var openxrSettingsType = Type.GetType("UnityEngine.XR.OpenXR.OpenXRSettings, Unity.XR.OpenXR");
        if (openxrSettingsType == null) return;

        var getSettings = openxrSettingsType.GetMethod("GetSettingsForBuildTargetGroup", BindingFlags.Public | BindingFlags.Static);
        if (getSettings == null) return;

        var settings = getSettings.Invoke(null, new object[] { group });
        if (settings == null) return;

        var getFeatures = openxrSettingsType.GetMethod("GetFeatures", Type.EmptyTypes);
        if (getFeatures == null) return;

        var features = (IEnumerable<ScriptableObject>)getFeatures.Invoke(settings, null);
        foreach (var f in features)
        {
            var name = f.GetType().FullName;
            // WHY: Ensure controller input works out-of-the-box; hand/eye when packages exist.
            if (name.Contains("OculusTouchControllerProfile") ||
                name.Contains("EyeGazeInteraction") ||
                name.Contains("HandTracking") ||
                name.Contains("Meta") && name.Contains("Quest"))
            {
                var enabledProp = f.GetType().GetProperty("enabled", BindingFlags.Public | BindingFlags.Instance);
                enabledProp?.SetValue(f, true);
                EditorUtility.SetDirty(f);
            }
        }
#endif
    }

    // ---------- Helpers for URP props ----------
    private static void TrySetProp<T>(object obj, string propName, T value)
    {
        var p = obj.GetType().GetProperty(propName, BindingFlags.Public | BindingFlags.Instance);
        if (p != null && p.CanWrite) { p.SetValue(obj, value); EditorUtility.SetDirty((UnityEngine.Object)obj); return; }

        // Fallback via SerializedObject
        var so = new SerializedObject((UnityEngine.Object)obj);
        var sp = so.FindProperty(ToBackingField(propName));
        if (sp != null)
        {
            if (typeof(T) == typeof(int)) sp.intValue = Convert.ToInt32(value);
            else if (typeof(T) == typeof(float)) sp.floatValue = Convert.ToSingle(value);
            else if (typeof(T) == typeof(bool)) sp.boolValue = Convert.ToBoolean(value);
            so.ApplyModifiedPropertiesWithoutUndo();
        }
    }

    private static void TrySetEnumProp(object obj, string propName, int enumIndex)
    {
        var so = new SerializedObject((UnityEngine.Object)obj);
        var sp = so.FindProperty(ToBackingField(propName));
        if (sp != null) { sp.intValue = enumIndex; so.ApplyModifiedPropertiesWithoutUndo(); }
    }

    private static void SetBoolIfExists(SerializedObject so, string field, bool value)
    {
        var p = so.FindProperty(field);
        if (p != null && p.propertyType == SerializedPropertyType.ObjectReference)
        {
            // When it's an object ref, null = disabled (URP uses presence of data)
            if (!value) p.objectReferenceValue = null;
        }
        else if (p != null && p.propertyType == SerializedPropertyType.Boolean)
        {
            p.boolValue = value;
        }
    }

    private static string ToBackingField(string publicName)
        => "m_" + char.ToUpperInvariant(publicName[0]) + publicName.Substring(1);
}
