// WHY: Small runtime tuner to prefer 90/120Hz and apply eye texture scale & optional foveation (if feature exists).
public class QuestMobileRuntimeTuner : MonoBehaviour
{
    [Range(0.7f, 1.4f)] public float eyeTextureScale = 1.0f;
    public float preferredRefreshRate = 90f; // 72/80/90/120 (device-dependent)

    private void Awake()
    {
        DontDestroyOnLoad(gameObject);
        StartCoroutine(ApplyXRRuntimeCaps());
    }

    private IEnumerator ApplyXRRuntimeCaps()
    {
        XRSettings.eyeTextureResolutionScale = eyeTextureScale;
        yield return new WaitForSeconds(0.5f);

        // Refresh rate request (OpenXR display subsystem)
        var displays = new System.Collections.Generic.List<XRDisplaySubsystem>();
        SubsystemManager.GetInstances(displays);
        foreach (var d in displays)
        {
            // API: TryRequestDisplayRefreshRate (available on Quest/OpenXR)
            var mi = d.GetType().GetMethod("TryRequestDisplayRefreshRate", BindingFlags.Instance | BindingFlags.Public);
            if (mi != null) mi.Invoke(d, new object[] { preferredRefreshRate });
        }

        // Optional: Foveated rendering (if present in your OpenXR feature)
        TryEnableFoveation(displays.FirstOrDefault());
    }

    private void TryEnableFoveation(XRDisplaySubsystem display)
    {
        if (display == null) return;
        // Reflect a common API shape:
        //   bool TrySetFoveatedRenderingLevel(int level);
        var mi = display.GetType().GetMethod("TrySetFoveatedRenderingLevel", BindingFlags.Instance | BindingFlags.Public);
        if (mi != null)
        {
            // 0=Off, 1=Low, 2=Med, 3=High (convention)
            try { mi.Invoke(display, new object[] { 2 }); } catch { /* ignore */ }
        }
    }

    // Convenience spawner for scenes that don't have it
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
    private static void EnsureExists()
    {
        if (FindObjectOfType<QuestMobileRuntimeTuner>() == null)
        {
            var go = new GameObject("QuestMobileRuntimeTuner");
            go.AddComponent<QuestMobileRuntimeTuner>();
        }
    }
}
