        ConfigurePlayerSettings();
        var scenes = CollectScenesOrCreate();
        EditorUserBuildSettings.SwitchActiveBuildTarget(BuildTargetGroup.Android, BuildTarget.Android);

        // Android caps
        PlayerSettings.SetUseDefaultGraphicsAPIs(BuildTarget.Android, false);
        PlayerSettings.SetGraphicsAPIs(BuildTarget.Android, new[] { UnityEngine.Rendering.GraphicsDeviceType.Vulkan, UnityEngine.Rendering.GraphicsDeviceType.OpenGLES3 });
        PlayerSettings.Android.targetArchitectures = AndroidArchitecture.ARM64;
        PlayerSettings.Android.minSdkVersion = AndroidSdkVersions.AndroidApiLevel29;
        PlayerSettings.SplashScreen.show = false;
        PlayerSettings.applicationIdentifier = BundleIdAndroid;
        PlayerSettings.bundleVersion = PlayerSettings.bundleVersion == string.Empty ? "0.1.0" : PlayerSettings.bundleVersion;

        // Use debug keystore for dev (WHY: faster iteration; set your release keystore in Player Settings for shipping)
        PlayerSettings.Android.useCustomKeystore = false;

        var outDir = Path.Combine(BuildRoot, "Quest3");
        Directory.CreateDirectory(outDir);
        var apkPath = Path.Combine(outDir, $"{ProductName}_Quest3.apk");

        var opts = new BuildPlayerOptions
        {
            scenes = scenes,
            target = BuildTarget.Android,
            locationPathName = apkPath,
            options = (DevelopmentBuild ? BuildOptions.Development | BuildOptions.AllowDebugging : BuildOptions.None)
        };

        var report = BuildPipeline.BuildPlayer(opts);
        PrintReport(report);

        if (report.summary.result == BuildResult.Succeeded)
        {
            UnityEngine.Debug.Log($"[Build] APK: {apkPath}");
            if (installAfter) TryAdbInstall(apkPath);
        }
        else
        {
            EditorUtility.DisplayDialog("Build Failed", "Android build failed. See Console.", "OK");
        }
    }

    private static void BuildWindowsExe()
    {
        EnsureSetup();
        ConfigurePlayerSettings();
        var scenes = CollectScenesOrCreate();
        EditorUserBuildSettings.SwitchActiveBuildTarget(BuildTargetGroup.Standalone, BuildTarget.StandaloneWindows64);

        PlayerSettings.applicationIdentifier = BundleIdWindows;
        PlayerSettings.SplashScreen.show = false;

        var outDir = Path.Combine(BuildRoot, "Windows", "GameWin64");
        Directory.CreateDirectory(outDir);
        var exePath = Path.Combine(outDir, "GameWin64.exe");

        var opts = new BuildPlayerOptions
        {
            scenes = scenes,
            target = BuildTarget.StandaloneWindows64,
            locationPathName = exePath,
            options = (DevelopmentBuild ? BuildOptions.Development | BuildOptions.AllowDebugging : BuildOptions.None)
        };

        var report = BuildPipeline.BuildPlayer(opts);
        PrintReport(report);

        if (report.summary.result == BuildResult.Succeeded)
        {
            UnityEngine.Debug.Log($"[Build] EXE: {exePath}");
            EditorUtility.RevealInFinder(exePath);
        }
        else
        {
            EditorUtility.DisplayDialog("Build Failed", "Windows build failed. See Console.", "OK");
        }
    }

