    private static void EnsureSetup()
    {
        // WHY: If you kept the earlier URP+OpenXR one-click script, run it here to avoid misconfig.
        var type = Type.GetType("Quest3URPAndOpenXRSetup, Assembly-CSharp-Editor");
        if (type != null)
        {
            var mi = type.GetMethod("DoEverything", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static);
            if (mi != null)
            {
                try { mi.Invoke(null, null); } catch (Exception ex) { UnityEngine.Debug.LogWarning("[Build] Setup invoke failed: " + ex.Message); }
            }
        }
    }

    private static void ConfigurePlayerSettings()
    {
        PlayerSettings.companyName = CompanyName;
        PlayerSettings.productName = ProductName;
        PlayerSettings.colorSpace = ColorSpace.Linear;
        PlayerSettings.MTRendering = true;
        PlayerSettings.graphicsJobs = true;
        PlayerSettings.SetManagedStrippingLevel(EditorUserBuildSettings.selectedBuildTargetGroup, ManagedStrippingLevel.High);
        UnityEngine.QualitySettings.vSyncCount = 0;
    }

    private static string[] CollectScenesOrCreate()
    {
        var scenes = AssetDatabase.FindAssets("t:Scene", new[] { ScenesFolder })
                                  .Select(AssetDatabase.GUIDToAssetPath)
                                  .OrderBy(p => p)
                                  .ToArray();

        if (scenes.Length > 0) return scenes;

        // Create sample scene identical to earlier bootstrap if none exist (WHY: idempotent builds)
        Directory.CreateDirectory(ScenesFolder);
        var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
        var bootstrap = new GameObject("Quest3Bootstrap");
        bootstrap.AddComponent<Bootstrap>(); // relies on your runtime scripts already in project
        var path = Path.Combine(ScenesFolder, "Main.unity");
        EditorSceneManager.SaveScene(scene, path);
        AssetDatabase.Refresh();
        return new[] { path };
    }

    private static void TryAdbInstall(string apkPath)
    {
        // WHY: Speed up iteration by side-loading straight to Quest 3 (if ADB is available)
        string sdk = GetAndroidSdkRoot();
        if (string.IsNullOrEmpty(sdk))
        {
            EditorUtility.DisplayDialog("ADB not found", "Set Android SDK in Preferences or install via Unity Hub.", "OK");
            return;
        }
        var adb = Path.Combine(sdk, "platform-tools", PlatformExe("adb"));
        if (!File.Exists(adb))
        {
            EditorUtility.DisplayDialog("ADB not found", $"Missing: {adb}", "OK");
            return;
        }

        Run(adb, "devices");
        var r = Run(adb, $"install -r \"{apkPath}\"");
        if (r.exitCode == 0) EditorUtility.DisplayDialog("Installed", "APK installed to connected device.", "OK");
        else EditorUtility.DisplayDialog("Install Failed", r.output, "OK");
    }

    private static (int exitCode, string output) Run(string file, string args)
    {
        try
        {
            var p = new Process();
            p.StartInfo.FileName = file;
            p.StartInfo.Arguments = args;
            p.StartInfo.CreateNoWindow = true;
            p.StartInfo.UseShellExecute = false;
            p.StartInfo.RedirectStandardOutput = true;
            p.StartInfo.RedirectStandardError = true;
            p.Start();
            var stdout = p.StandardOutput.ReadToEnd();
            var stderr = p.StandardError.ReadToEnd();
            p.WaitForExit();
            var text = stdout + "\n" + stderr;
            UnityEngine.Debug.Log($"[ADB] {file} {args}\n{text}");
            return (p.ExitCode, text);
        }
        catch (Exception ex)
        {
            return (-1, ex.Message);
        }
    }

    private static string GetAndroidSdkRoot()
    {
        // Try Unity’s configured SDK first
        var type = Type.GetType("UnityEditor.Android.AndroidExternalToolsSettings, UnityEditor");
        if (type != null)
        {
            var p = type.GetProperty("sdkRootPath", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static);
            if (p != null)
            {
                var v = p.GetValue(null) as string;
                if (!string.IsNullOrEmpty(v) && Directory.Exists(v)) return v;
            }
        }
#if UNITY_2021_3_OR_NEWER
        var env = Environment.GetEnvironmentVariable("ANDROID_SDK_ROOT");
        if (!string.IsNullOrEmpty(env) && Directory.Exists(env)) return env;
#endif
        return null;
    }

    private static string PlatformExe(string name) => Application.platform == RuntimePlatform.WindowsEditor ? name + ".exe" : name;

    private static void PrintReport(BuildReport report)
    {
        var s = report.summary;
        UnityEngine.Debug.Log($"[Build] Result={s.result}, Platform={s.platform}, Size={(s.totalSize/1_000_000f):0.0} MB, Time={s.totalTime.TotalSeconds:0.0}s");
        if (s.result != BuildResult.Succeeded)
        {
            foreach (var step in report.steps)
                foreach (var msg in step.messages)
                    if (msg.type == LogType.Error || msg.type == LogType.Exception)
                        UnityEngine.Debug.LogError($"[Build] {msg.content}");
        }
    }
}
